import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { StorageError, type StorageProvider, type StoredObject } from './storage.types';

/**
 * Private local storage for development and single-node deployments. Keys are
 * generated by the API, but are still validated to prevent path traversal.
 */
@Injectable()
export class LocalStorageAdapter implements StorageProvider {
  readonly name = 'local';
  private readonly logger = new Logger(LocalStorageAdapter.name);
  private readonly baseDir: string;

  constructor(private readonly config: ConfigService) {
    this.baseDir = resolve(process.cwd(), config.get<string>('STORAGE_LOCAL_DIR', './storage'));
  }

  private pathFor(key: string): string {
    const normalised = key.replace(/\\/g, '/');
    if (!normalised || normalised.startsWith('/') || normalised.split('/').includes('..')) {
      throw new StorageError('Invalid storage key', this.name);
    }
    const fullPath = resolve(this.baseDir, normalised);
    if (!fullPath.startsWith(`${this.baseDir}/`)) {
      throw new StorageError('Storage key escapes the configured directory', this.name);
    }
    return fullPath;
  }

  async putObject(key: string, body: Buffer, contentType: string): Promise<StoredObject> {
    const path = this.pathFor(key);
    try {
      await mkdir(dirname(path), { recursive: true, mode: 0o700 });
      await writeFile(path, body, { mode: 0o600 });
      return { key, sizeBytes: body.byteLength, contentType };
    } catch (error) {
      this.logger.error(`Local storage write failed: ${(error as Error).message}`);
      throw new StorageError('Could not persist attachment', this.name);
    }
  }

  async getObject(key: string): Promise<{ body: Buffer; contentType: string | null }> {
    try {
      return { body: await readFile(this.pathFor(key)), contentType: null };
    } catch {
      throw new StorageError('Attachment content not found', this.name);
    }
  }

  async deleteObject(key: string): Promise<void> {
    try {
      await unlink(this.pathFor(key));
    } catch (error) {
      const code = (error as NodeJS.ErrnoException).code;
      if (code !== 'ENOENT') throw new StorageError('Could not delete attachment content', this.name);
    }
  }
}
